constructor(window) {
  this.window = window;
}
openConversationForMessages(messages) {
  if (messages.length < 1) {
    return;
  }
  try {
    this._items = [];
    this._msgHdr = messages[0];
    this._queries = [Gloda.getMessageCollectionForHeaders(messages, this)];
  } catch (e) {
    console.error(e);
  }
}
